class Myiterator:
    def __init__(self, start, stop, step):
        self.start = start
        self.stop = stop
        self.step = step

    def __iter__(self):
        return self

    def __next__(self):
        self.num = self.start
        self.start += self.step
        if self.num > self.stop:
            raise StopIteration('End of numbers')
        else:
            return self.num

myiterator = Myiterator(1, 5, 2)
print(next(myiterator))
print(next(myiterator))
print(next(myiterator))

class Rectangle:
    def __init__(self, length, width):
        self.length = length
        self.width = width
        self.midpoint = f'The midpoint of this rectangle is {length/2, width/2}'

    def area(self):
        return self.length * self.width

    def hstretch(self, factor):
        self.width = factor * self.width

class Square(Rectangle):
    def __init__(self, side):
        self.side = side
        super().__init__(side, side)

a_particular_square = Square(4)
print(a_particular_square.width == a_particular_square.length)
a_particular_square.hstretch(2)
print(a_particular_square.width == a_particular_square.length)
